mapper.update:
	/*
	 * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsContentlistMapper :  콘텐츠활용신청(상태값 변경)
	 * 2023.06.16 수정 - Jeong.Won.Je
	 */
        UPDATE 
                AYE100 
        SET 
                APRV_STTS_SE_CD     =   #{APRV_STTS_SE_CD}
                , LAST_MDFR_ID      =   #{loginId}
                , LAST_MDFCN_DT     =   SYSDATE
        WHERE   1=1
        AND     BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}                                 
        AND     BBSCTT_TYPE_SE_CD   =   #{BBSCTT_TYPE_SE_CD}

	/*
     * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsContentlistMapper.insertBbsContentReply :  
     * 2023.06.16 추가 - Jeong.Won.Je
     */
		INSERT INTO AYE120 
		       (
				RETE_ESNTAL_NO
				, BBSCTT_ESNTAL_NO
				, BBSCTT_TYPE_SE_CD
				, RETE_CN
				, CNTN_IP_ADDR
				, FRST_RGTR_ID
				, FRST_REG_DT
			   ) 
		VALUES (
				AYE120_SQ01.NEXTVAL
				, #{BBSCTT_ESNTAL_NO}
				, #{BBSCTT_TYPE_SE_CD}
				, #{RETE_CN}
				, #{loginIp}
				, #{loginId}
				, SYSDATE
			   )
